50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "household_size")
71	    private Integer householdSize;
72	
73	    @Column(name = "bulk_signup_warning")
74	    private boolean bulkSignupWarning;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    /**
108	     * Stores the email in its canonical lower-cased form so it is always persisted and
109	     * returned lower-cased, regardless of the casing supplied by the client.
110	     */
111	    public void setEmail(String email) {
112	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
113	    }
114	
115	    public String getPostcode() {
116	        return this.postcode;
117	    }
118	
119	    public void setPostcode(String postcode) {
120	        this.postcode = postcode;
121	    }
122	
123	    public LocalDate getRegistrationDate() {
