128	        this.registrationDate = registrationDate;
129	    }
130	
131	    public String getCustomerCode() {
132	        return this.customerCode;
133	    }
134	
135	    public void setCustomerCode(String customerCode) {
136	        this.customerCode = customerCode;
137	    }
138	
139	    public String getHouseholdId() {
140	        return this.householdId;
141	    }
142	
143	    public void setHouseholdId(String householdId) {
144	        this.householdId = householdId;
145	    }
146	
147	    public Integer getNamesakeCount() {
