171	    /**
172	     * The derived key that uniquely identifies an owner for duplicate detection: the normalized
173	     * telephone, the (lower-cased) email or the empty string when absent, and the household id or
174	     * the empty string when the owner belongs to no household, joined with {@code '|'}. Two owners
175	     * are duplicates only when their whole identity keys are equal, so members of the same household
176	     * with different telephones (or an owner reusing only a telephone or only an email) remain
177	     * distinct.
178	     */
179	    @Transient
180	    public String getIdentityKey() {
181	        return this.telephone + "|"
182	            + (this.email == null ? "" : this.email) + "|"
183	            + (this.householdId == null ? "" : this.householdId);
184	    }
185	
186	    /**
187	     * On first persist, default the registration date to the server's current date when the
188	     * client did not supply one, then roll the effective date forward so it always falls on a
189	     * business day (a weekend moves to the following Monday).
190	     */
191	    @PrePersist
192	    private void defaultRegistrationDate() {
193	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
194	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
195	    }
196	
197	    protected Set<Pet> getPetsInternal() {
198	        if (this.pets == null) {
199	            this.pets = new HashSet<>();
